-- =====================================================================================
-- Platon, 24.11.2026 (P01): доставка Uzum Tezkor — API и cron.
--
-- База — platon, не microservice. Сначала в microservice должна быть миграция
-- 01-DDL.sql: стадии вызывают её функции project.uzum_*.
-- Файл собран генератором tools/gen_p01.py — править там, потом пересобрать.
--
-- Эндпоинты (12, стадий 32), группа «Uzum Tezkor (Mutalib)»:
--   POST  v1/uzum/calculate        bearer  Uzum: цена доставки от объекта до адреса
--   POST  v1/uzum/claim/create     bearer  Uzum: вызвать курьера
--   POST  v1/uzum/claim/accept     bearer  Uzum: подтвердить черновик — начать поиск курьера
--   GET   v1/uzum/claim/info       bearer  Uzum: доставка со свежим статусом из claims/info
--   POST  v1/uzum/claim/cancel     bearer  Uzum: отменить доставку
--   GET   v1/uzum/claim/courier    bearer  Uzum: курьер — имя, телефон, координаты, ссылка отслеживания
--   GET   v1/uzum/claims           bearer  Uzum: доставки объектов оператора
--   GET   v1/uzum/points           bearer  Uzum: где доступна доставка — точки забора без токенов
--   GET   v1/uzum/me               bearer  Uzum: мой id и права
--   POST  v1/uzum/callback         нет     Uzum: callback о смене статуса — без авторизации, secret в адресе; статус берётся из claims/info
--   POST  v1/uzum/sync             basic   Uzum: cron UzumSync — claims/info по активным доставкам без новостей, повтор create для new
--   GET   v1/uzum/diag             bearer  Uzum: диагностика платформы — что делает http.post на 404 и какой режим тела понимает Uzum
--
-- Запуск: DataGrip, консоль на базе platon → весь файл (Ctrl+A, Ctrl+Enter). Повторный запуск
-- ничего не задвоит: эндпоинт с тем же методом и путём и задача с тем же именем пропускаются.
--
-- Как устроено:
--   * У эндпоинтов с вызовом Uzum три стадии: prep (SQL собирает вызовы и токен точки),
--     uz (JS выполняет их через http.post / http.get, ошибку HTTP ловит и кладёт в _error),
--     _body (SQL разбирает ответ, пишет заявку и отдаёт её). У cancel — две пары: сначала
--     cancel-info, потом cancel (платная — только с allow_paid).
--   * has_transaction = false: строка заявки с request_id сохраняется до вызова Uzum, поэтому
--     сбой связи не теряет заявку, а повтор (cron) не создаёт второго курьера.
--   * callback — без авторизации (Uzum не подписывает запросы): секрет заявки в адресе, а
--     статус берётся из claims/info, поэтому поддельный callback ничего не меняет.
--   * cron UzumSync (* * * * *) — basic, заголовок Authorization копируется из
--     TokenUpdater (как в P01/P02 бонусных карт).
--   * id — отрицательные, ниже текущего минимума; подстановки платформы (двоеточие, решётка,
--     доллар перед именем) в JSON записаны escape-ами \u003a, \u0023, \u0024, чтобы DataGrip не
--     принял их за свои параметры. В базе это обычные символы — их покажет проверка 2.
--
-- После вставки — первым делом GET v1/uzum/diag (раздел «Проверка на сервере» в 00-Обзор.md).
-- =====================================================================================

begin;

-- 1. Эндпоинты
insert into api_endpoints (id, state, version, created_at, attributes, method, path, auth_handler,
                           has_transaction, group_by, result_cached_seconds, note)
select (select least(min(id), 0) from api_endpoints) - row_number() over (order by v.ord),
       1, 1, now(), '{}', v.method, v.path, v.auth, v.tx, 'Uzum Tezkor (Mutalib)', 0, v.note
from (values (1, 'POST', 'v1/uzum/calculate', 'bearer', false, 'Uzum: цена доставки от объекта до адреса (place_id, branch_id, lon, lat, address, taxi_class, weight). Ничего не создаёт'),
             (2, 'POST', 'v1/uzum/claim/create', 'bearer', false, 'Uzum: вызвать курьера (оператор). Черновик с ценой; auto_accept — сразу заказ. Повтор с тем же order_ref — та же доставка'),
             (3, 'POST', 'v1/uzum/claim/accept', 'bearer', false, 'Uzum: подтвердить черновик — начать поиск курьера (id). После этого заказ не меняется, только отмена'),
             (4, 'GET', 'v1/uzum/claim/info', 'bearer', false, 'Uzum: доставка со свежим статусом из claims/info (id). Оператор или тот, кто создал'),
             (5, 'POST', 'v1/uzum/claim/cancel', 'bearer', false, 'Uzum: отменить доставку (id; allow_paid = true — согласие на платную отмену после забора)'),
             (6, 'GET', 'v1/uzum/claim/courier', 'bearer', false, 'Uzum: курьер — имя, телефон, координаты, ссылка отслеживания (id)'),
             (7, 'GET', 'v1/uzum/claims', 'bearer', false, 'Uzum: доставки объектов оператора (place_id, status — статус или этап, active, limit, offset)'),
             (8, 'GET', 'v1/uzum/points', 'bearer', false, 'Uzum: где доступна доставка — точки забора без токенов (place_id)'),
             (9, 'GET', 'v1/uzum/me', 'bearer', false, 'Uzum: мой id и права (user_id — для project.uzum_operators)'),
             (10, 'POST', 'v1/uzum/callback', null::varchar, false, 'Uzum: callback о смене статуса — без авторизации, secret в адресе; статус берётся из claims/info'),
             (11, 'POST', 'v1/uzum/sync', 'basic', false, 'Uzum: cron UzumSync — claims/info по активным доставкам без новостей, повтор create для new'),
             (12, 'GET', 'v1/uzum/diag', 'bearer', false, 'Uzum: диагностика платформы — что делает http.post на 404 и какой режим тела понимает Uzum (администратор; place_id)'))
         as v(ord, method, path, auth, tx, note)
where not exists (select 1 from api_endpoints e where e.method = v.method and e.path = v.path);

-- 2. Стадии
insert into api_stages (id, endpoint_id, sort_order, alias, handler, serialize_result, state, version, created_at,
                        attributes, access_condition)
select (select least(min(id), 0) from api_stages) - row_number() over (order by s.ord),
       e.id, s.sort_order, s.alias, s.handler, true, 1, 1, now(), s.attributes::json, null
from api_endpoints e
         join (values (1, 'POST', 'v1/uzum/calculate', 10, 'prep', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_calc_prepare(\u0024user.id::uuid, \u0023place_id::uuid, \u0023branch_id::uuid, \u0023lon::numeric, \u0023lat::numeric,\n                                        \u0023address::varchar, \u0023taxi_class::varchar, \u0023weight::numeric)"}'),
                      (2, 'POST', 'v1/uzum/calculate', 20, 'uz', 'js_eval_handler',
                       '{"js_eval": "{\"code\":\"// Uzum Tezkor: выполнить вызовы из стадии prep. calls — JSON-массив\\n// [{key, method, url, token, body, body_mode}], его собирает SQL-функция project.uzum_*.\\n// Ответ — объект {key: ответ Uzum}; ошибку HTTP кладём в _error, разбирает её SQL.\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\",\"es5\":\"return (function(){\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\\n})();\"}"}'),
                      (3, 'POST', 'v1/uzum/calculate', 30, '_body', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_calc_result(\u003auz::text, \u003aprep.taxi_class::varchar)"}'),
                      (4, 'POST', 'v1/uzum/claim/create', 10, 'prep', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_create_prepare(\u0024user.id::uuid, \u0023place_id::uuid, \u0023branch_id::uuid, \u0023order_ref::varchar,\n                                          \u0023recipient_name::varchar, \u0023recipient_phone::varchar,\n                                          \u0023address::varchar, \u0023lon::numeric, \u0023lat::numeric,\n                                          \u0023porch::varchar, \u0023sfloor::varchar, \u0023sflat::varchar,\n                                          \u0023door_code::varchar, \u0023address_comment::varchar,\n                                          \u0023comment::varchar, \u0023items::text, \u0023taxi_class::varchar,\n                                          \u0023optional_return::boolean, \u0023auto_accept::boolean)"}'),
                      (5, 'POST', 'v1/uzum/claim/create', 20, 'uz', 'js_eval_handler',
                       '{"js_eval": "{\"code\":\"// Uzum Tezkor: выполнить вызовы из стадии prep. calls — JSON-массив\\n// [{key, method, url, token, body, body_mode}], его собирает SQL-функция project.uzum_*.\\n// Ответ — объект {key: ответ Uzum}; ошибку HTTP кладём в _error, разбирает её SQL.\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\",\"es5\":\"return (function(){\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\\n})();\"}"}'),
                      (6, 'POST', 'v1/uzum/claim/create', 30, '_body', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_save(\u0024user.id::uuid, \u003aprep.id::uuid, ''create'', \u003auz::text)"}'),
                      (7, 'POST', 'v1/uzum/claim/accept', 10, 'prep', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_op_prepare(\u0024user.id::uuid, \u0023id::uuid, ''accept'')"}'),
                      (8, 'POST', 'v1/uzum/claim/accept', 20, 'uz', 'js_eval_handler',
                       '{"js_eval": "{\"code\":\"// Uzum Tezkor: выполнить вызовы из стадии prep. calls — JSON-массив\\n// [{key, method, url, token, body, body_mode}], его собирает SQL-функция project.uzum_*.\\n// Ответ — объект {key: ответ Uzum}; ошибку HTTP кладём в _error, разбирает её SQL.\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\",\"es5\":\"return (function(){\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\\n})();\"}"}'),
                      (9, 'POST', 'v1/uzum/claim/accept', 30, '_body', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_save(\u0024user.id::uuid, \u003aprep.id::uuid, ''accept'', \u003auz::text)"}'),
                      (10, 'GET', 'v1/uzum/claim/info', 10, 'prep', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_op_prepare(\u0024user.id::uuid, \u0023id::uuid, ''info'')"}'),
                      (11, 'GET', 'v1/uzum/claim/info', 20, 'uz', 'js_eval_handler',
                       '{"js_eval": "{\"code\":\"// Uzum Tezkor: выполнить вызовы из стадии prep. calls — JSON-массив\\n// [{key, method, url, token, body, body_mode}], его собирает SQL-функция project.uzum_*.\\n// Ответ — объект {key: ответ Uzum}; ошибку HTTP кладём в _error, разбирает её SQL.\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\",\"es5\":\"return (function(){\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\\n})();\"}"}'),
                      (12, 'GET', 'v1/uzum/claim/info', 30, '_body', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_save(\u0024user.id::uuid, \u003aprep.id::uuid, ''info'', \u003auz::text)"}'),
                      (13, 'POST', 'v1/uzum/claim/cancel', 10, 'prep', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_op_prepare(\u0024user.id::uuid, \u0023id::uuid, ''cancel_info'')"}'),
                      (14, 'POST', 'v1/uzum/claim/cancel', 20, 'uz', 'js_eval_handler',
                       '{"js_eval": "{\"code\":\"// Uzum Tezkor: выполнить вызовы из стадии prep. calls — JSON-массив\\n// [{key, method, url, token, body, body_mode}], его собирает SQL-функция project.uzum_*.\\n// Ответ — объект {key: ответ Uzum}; ошибку HTTP кладём в _error, разбирает её SQL.\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\",\"es5\":\"return (function(){\\nvar p = variables.prep;\\nvar raw = p ? p.calls : null;\\nif (raw && raw.value !== undefined) {\\n    raw = raw.value;\\n}\\nvar calls = raw ? JSON.parse(String(raw)) : [];\\nvar out = {};\\nfor (var i = 0; i < calls.length; i++) {\\n    var c = calls[i];\\n    var h = {\\\"Authorization\\\": \\\"Bearer \\\" + c.token, \\\"Content-Type\\\": \\\"application/json\\\", \\\"Accept-Language\\\": \\\"ru\\\"};\\n    try {\\n        if (c.method === \\\"GET\\\") {\\n            out[c.key] = http.get(c.url, h);\\n        } else {\\n            var b = (c.body === null || c.body === undefined) ? \\\"{}\\\" : c.body;\\n            out[c.key] = http.post(c.url, c.body_mode === \\\"object\\\" ? JSON.parse(b) : b, h);\\n        }\\n    } catch (e) {\\n        out[c.key] = {\\\"_error\\\": String(e && e.message ? e.message : e)};\\n    }\\n}\\nreturn out;\\n})();\"}"}'),
                      (15, 'POST', 'v1/uzum/claim/cancel', 30, 'step', 'sql_select',
                       '{"datasource": "project", "sql_result_type": "map", "sql": "select * from project.uzum_cancel_decide(\u0024user.id::uuid, \u003aprep.id::uuid, \u003auz::text, \u0023allow_paid::boolean)"}'),
                      (16, 'POST', 'v1/uzum/claim/cancel', 40, 'uz2', 'js_eval_handler',
